export const AFFILIATE_MAX_AGE = 395 * 24 * 60 * 60;

export function affiliateCookies(url, now = new Date()) {
  const query = new URL(url, 'https://fixture.invalid').searchParams;
  const expires = new Date(now.getTime() + AFFILIATE_MAX_AGE * 1000).toUTCString();
  // URLSearchParams: first duplicate wins; an explicitly empty value creates an
  // empty cookie. Domain and SameSite omitted, not inferred from source.
  return ['cjevent', 'loyaltysignal'].filter(name => query.has(name)).map(name =>
    `${name}=${encodeURIComponent(query.get(name))}; Path=/; Secure; Max-Age=${AFFILIATE_MAX_AGE}; Expires=${expires}`);
}

